mapper.select:
		select t.* from
		(


				DATE_FORMAT(CAVS.CHB_SUBMIT_DEADLINE,'%Y-%m-%d') >= #{submitDeadLineStart,jdbcType=VARCHAR}


				and DATE_FORMAT(CAVS.CHB_SUBMIT_DEADLINE,'%Y-%m-%d') <= #{submitDeadLineEnd,jdbcType=VARCHAR}



				#{item,jdbcType=VARCHAR}




				#{item,jdbcType=VARCHAR}



				and DATE_FORMAT(CAVS.STATUS_DATE,'%Y-%m-%d') >= #{statusDateStart,jdbcType=VARCHAR}


				and DATE_FORMAT(CAVS.STATUS_DATE,'%Y-%m-%d') <= #{statusDateEnd,jdbcType=VARCHAR}


				and DATE_FORMAT(CAVS.SUBMIT_TIME,'%Y-%m-%d') >= #{submitDateStart,jdbcType=VARCHAR}


				and DATE_FORMAT(CAVS.SUBMIT_TIME,'%Y-%m-%d') <= #{submitDateEnd,jdbcType=VARCHAR}


				and DATE_FORMAT(CAVS.VAL_DATE,'%Y-%m-%d') >= #{valDateStart,jdbcType=VARCHAR}


				and DATE_FORMAT(CAVS.VAL_DATE,'%Y-%m-%d') <= #{valDateEnd,jdbcType=VARCHAR}



             		#{submitFeedbackStatus,jdbcType=VARCHAR}



				and CAVS.STATUS = #{status,jdbcType=VARCHAR}


				and upper(CAVS.ASSET_CODE) like concat_ws('','%',upper(#{assetCodeLike,jdbcType=VARCHAR}),'%')


		)t order by t.valDate,t.assetCode

select t.* from
(



	 		       1=1

	 	 			and trim(CAVS.REGIST_SEQNO) = #{regist.registSeqno} 


	 	 			and CAVS.STATUS = #{regist.status} 


	 	 			and CAVS.SEND_STATUS = #{regist.sendStatus} 


	 	 			and CAVS.REGIST_BANK_CODE = #{regist.registBankCode} 




)t

mapper.update:
update CHB_AST_VAL_SUB sub
sub.SEND_STATUS = '03', sub.SUBMIT_FEEDBACK_STATUS = '03', sub.submit_time = NOW(), sub.UPDATE_TIME = NOW(), sub.STATUS_DATE = NOW()
trim(sub.REGIST_SEQNO) = #{regist.registSeqno}

